+      '/logout': 'Logout',
+      '/order-online': 'Order Online',
+      '/about': 'Our Story',
+      '/careers': 'Join the Team',
+      '/contact': 'Contact Us',
+      '/privacy-policy': 'Privacy'
+    };
+    const segments = window.location.pathname.split('/').filter(Boolean);
+    if (segments[segments.length - 1] === 'index.html') segments.pop();
+    const crumbs = [{ label: 'Home', href: '/' }];
+
+    segments.forEach((segment, index) => {
+      const href = '/' + segments.slice(0, index + 1).join('/');
+      let label = segment;
+      try {
+        label = decodeURIComponent(segment);
+      } catch {
+        // Keep the original segment if the URL contains invalid encoding.
+      }
+      label = label.replace(/[-_]/g, ' ').replace(/\b\w/g, letter => letter.toUpperCase());
+      crumbs.push({ label: pageNames[href] || label, href });
+    });
+
+    breadcrumbList.replaceChildren();
+    crumbs.forEach((crumb, index) => {
+      const item = document.createElement('li');
+      if (index > 0) {
+        const separator = document.createElement('span');
+        separator.className = 'separator';
+        separator.setAttribute('aria-hidden', 'true');
+        separator.textContent = '›';
+        item.append(separator);
+      }
+      const isCurrent = index === crumbs.length - 1;
+      const label = document.createElement(isCurrent ? 'span' : 'a');
+      label.textContent = crumb.label;
+      if (isCurrent) {
+        label.setAttribute('aria-current', 'page');
+      } else {
+        label.setAttribute('href', crumb.href);
+      }
+      item.append(label);
+      breadcrumbList.append(item);
+    });
+  </script>
+
 </body>

