+nav a[aria-current="page"] {
+  color: var(--accent);
+}
+
+.logo a {
+  font: inherit;
+  letter-spacing: inherit;
+}
+
+.page-intro {
+  text-align: center;
+  padding-top: 2rem;
+}
+
+@media (max-width: 640px) {
+  nav {
+    flex-wrap: wrap;
+    gap: 0.75rem;
+  }
+
+  nav ul {
+    flex-wrap: wrap;
+    gap: 0.75rem;
+  }
+
+  nav ul li {
+    margin-left: 0;
+  }
+}

