+const params=new URLSearchParams(location.search);
+if(params.has('date'))$('dateInput').value=params.get('date');if(params.has('time'))$('timeInput').value=params.get('time');if(zones.some(z=>z.tz===params.get('host')))$('hostTzSelect').value=params.get('host');
