+// Browser adaptation: progressive 2x2 subpixel sampling and RGBA output.
+// Original tracing core above by Kevin Beason; see LICENSE.txt.
+#include <stdint.h>
+#include <new>
+static Vec *accum = nullptr;
+static unsigned char *pixels = nullptr;
+static int width, height;
+static unsigned int sceneSeed;
+extern "C" {
+int init_scene(int w, int h, unsigned int seed) {
+  if (w < 1 || h < 1 || w > 1920 || h > 1440) return 0;
