+        accum[a]=accum[a]+radiance(Ray(cam.o+d*140,d.norm()),0,Xi);
+        Vec avg=accum[a]*(1.0/(pass+1));
+        color=color+Vec(clamp(avg.x),clamp(avg.y),clamp(avg.z))*.25;
+      }
+      int i=(row*width+x)*4;
+      pixels[i]=toInt(color.x); pixels[i+1]=toInt(color.y); pixels[i+2]=toInt(color.z);
+    }
+  }
+}
+}
+#ifdef SMALLPT_PREVIEW
+int main() {
+  init_scene(800,600,42);
+  set_color(0,.40,.55,.43); set_color(1,.70,.40,.30);
+  for(int p=0;p<64;p++) render_rows(0,600,p);
+  FILE *f=fopen("/tmp/smallpt-preview.ppm","wb");
+  fprintf(f,"P6\n800 600\n255\n");
+  for(int i=0;i<800*600;i++) fwrite(pixels+i*4,1,3,f);
+  fclose(f);
+}
