+const base = import.meta.env.BASE_URL;
+const canvas = document.querySelector<HTMLCanvasElement>('#render-canvas')!;
+const context = canvas.getContext('2d')!;
+const status = document.querySelector<HTMLElement>('#status')!;
+const sampleCount = document.querySelector<HTMLElement>('#sample-count')!;
+const elapsed = document.querySelector<HTMLElement>('#elapsed')!;
+const progress = document.querySelector<HTMLElement>('#progress')!;
+const fill = document.querySelector<HTMLElement>('#progress-fill')!;
+const pause = document.querySelector<HTMLButtonElement>('#pause')!;
+const resolution = document.querySelector<HTMLSelectElement>('#resolution')!;
+const colorInputs = [...document.querySelectorAll<HTMLInputElement>('input[data-sphere]')];
+const qualityButtons = [...document.querySelectorAll<HTMLButtonElement>('[data-samples]')];
+let samples = 64;
+let worker: Worker | undefined;
+let paused = false;
+let rendering = false;
+let started = 0;
+let pauseStarted = 0;
+let pausedTime = 0;
+let timer: ReturnType<typeof setInterval> | undefined;
+let sceneNumber = 1;
+let hasFrame = false;
+let previewLoaded = false;
+let pendingDownload = false;
+const preview = new Image();
+preview.onload = () => {
+  previewLoaded = true;
+  if (!hasFrame) context.drawImage(preview, 0, 0, canvas.width, canvas.height);
+  if (pendingDownload) { pendingDownload = false; download(); }
+};
+preview.src = `${base}smallpt-preview.png`;
+
+function updateElapsed() {
+  if (!paused) elapsed.textContent = `${((performance.now() - started - pausedTime) / 1000).toFixed(1)}s`;
+}
+function setProgress(value: number) {
+  const percent = Math.round(value * 100);
+  fill.style.width = `${percent}%`;
+  progress.setAttribute('aria-valuenow', String(percent));
+}
+function setPauseIcon(isPaused: boolean) {
+  pause.setAttribute('aria-label', isPaused ? 'Resume render' : 'Pause render');
+  pause.title = isPaused ? 'Resume render' : 'Pause render';
+  pause.innerHTML = isPaused
+    ? '<svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6"><path d="m8 5 11 7-11 7z"/></svg>'
+    : '<svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6"><path d="M9 5v14M15 5v14"/></svg>';
+}
+function fail(message: string) {
+  worker?.terminate();
+  rendering = false;
+  clearInterval(timer);
+  pause.disabled = true;
+  status.textContent = message;
+  document.querySelector<HTMLElement>('#status-light')!.style.background = '#b87950';
+}
+function render() {
+  worker?.terminate();
+  clearInterval(timer);
+  if (!('WebAssembly' in window) || !('Worker' in window)) {
+    fail('This browser does not support the renderer.');
+    return;
+  }
+  paused = false;
+  rendering = true;
+  pausedTime = 0;
+  started = performance.now();
+  pause.disabled = false;
+  setPauseIcon(false);
+  setProgress(0);
+  sampleCount.textContent = '0';
+  elapsed.textContent = '0.0s';
+  status.textContent = 'Tracing the light…';
+  document.querySelector<HTMLElement>('#status-light')!.style.background = '#69a279';
+  const width = Number(resolution.value);
+  const height = width * 3 / 4;
+  const colors = colorInputs.map(input => ({
+    id: Number(input.dataset.sphere),
+    rgb: [1, 3, 5].map(offset => Math.min(.999, parseInt(input.value.slice(offset, offset + 2), 16) / 255)),
+  }));
+  try {
+    worker = new Worker(`${base}wasm/render-worker.js`, { type: 'module' });
+    worker.onerror = () => fail('Renderer unavailable. Try rendering again.');
+    worker.onmessage = ({ data }) => {
+      if (data.type === 'progress') setProgress(data.progress);
+      if (data.type === 'frame') {
+        if (canvas.width !== width || canvas.height !== height) { canvas.width = width; canvas.height = height; }
+        context.putImageData(new ImageData(data.pixels, width, height), 0, 0);
+        hasFrame = true;
