+emcc renderer/smallpt.cpp -O3 --no-entry -s WASM=1 -s MODULARIZE=1 -s EXPORT_NAME=createSmallpt -s ENVIRONMENT=worker -s FILESYSTEM=0 -s EXPORTED_FUNCTIONS='["_init_render","_set_color","_render_rows"]' -s EXPORTED_RUNTIME_METHODS='["HEAPU8"]' -s INITIAL_MEMORY=16777216 -o public/renderer/smallpt.js
