+/* Later layers take precedence without increasing selector specificity. */
+@layer tokens, reset, base, layout, components, utilities;
+
+@layer tokens {
+  :root {
+    --color-primary: #4e342e;
+    --color-secondary: #d7ccc8;
+    --color-accent: #ffab40;
+    --color-text: #3e2723;
+    --color-page: #fafafa;
+    --color-surface: #fff;
+    --color-on-primary: #fff;
+    --color-primary-hover: #3e2723;
+    --color-hero-overlay: rgb(0 0 0 / 50%);
+
+    --font-family-body: 'Segoe UI', Tahoma, Geneva, Verdana, sans-serif;
+    --font-size-small: 0.85rem;
+    --font-size-nav: 0.9rem;
+    --font-size-logo: 1.5rem;
+    --font-size-hero: 3rem;
+    --font-weight-bold: 700;
+    --line-height-body: 1.6;
+    --letter-spacing-logo: 1px;
+
+    --space-1: 0.3125rem;
+    --space-2: 0.625rem;
+    --space-3: 0.75rem;
+    --space-4: 0.9375rem;
+    --space-5: 1rem;
+    --space-6: 1.25rem;
+    --space-7: 2.5rem;
+
+    --radius-small: 0.25rem;
+    --radius-button: 0.3125rem;
+    --radius-card: 0.5rem;
+    --border-width: 1px;
+    --shadow-card: 0 2px 5px rgb(0 0 0 / 10%);
+    --duration-interaction: 0.3s;
+    --focus-ring-width: 2px;
+    --focus-ring-offset: 3px;
+
+    --size-content: 68.75rem;
+    --size-card-min: 15.625rem;
+    --size-hero: 60vh;
+    --gutter-nav: 5%;
+    --z-index-nav: 1000;
+    --image-hero: url('https://images.unsplash.com/photo-1495474472287-4d71bcdd2085?auto=format&fit=crop&w=1350&q=80');
+  }
+}
+
+@layer reset {
+  :where(*, *::before, *::after) {
+    box-sizing: border-box;
+  }
+
+  :where(body, h1, h2, h3, p, ul) {
+    margin: 0;
+    padding: 0;
+  }
+}
+
+@layer base {
+  body {
+    font-family: var(--font-family-body);
+    line-height: var(--line-height-body);
+    color: var(--color-text);
+    background-color: var(--color-page);
+  }
+
+  :where(a:focus-visible) {
+    outline: var(--focus-ring-width) solid currentColor;
+    outline-offset: var(--focus-ring-offset);
+  }
+
+  @media (prefers-reduced-motion: reduce) {
+    :root {
+      --duration-interaction: 0s;
+    }
+  }
+}
+
+@layer layout {
+  .container {
+    max-inline-size: var(--size-content);
+    margin-block: var(--space-7);
+    margin-inline: auto;
+    padding-inline: var(--space-6);
+  }
+
+  .grid {
+    display: grid;
+    grid-template-columns: repeat(auto-fit, minmax(min(100%, var(--size-card-min)), 1fr));
+    gap: var(--space-6);
+    margin-block-start: var(--space-6);
+  }
+}
+
+@layer components {
+  /* Shared treatments stay low-specificity so component rules can extend them. */
+  :where(.site-nav, .btn) {
+    color: var(--color-on-primary);
+    background-color: var(--color-primary);
+  }
+
+  :where(.site-nav a, .footer-links a, .btn) {
+    text-decoration: none;
+  }
+
+  :where(.hero, .card, .site-footer) {
+    text-align: center;
+  }
+
+  .site-nav {
+    display: flex;
+    flex-wrap: wrap;
+    justify-content: space-between;
+    align-items: center;
+    gap: var(--space-5) var(--space-6);
+    position: sticky;
+    inset-block-start: 0;
+    z-index: var(--z-index-nav);
+    padding-block: var(--space-5);
+    padding-inline: var(--gutter-nav);
+  }
+
+  .logo {
+    font-size: var(--font-size-logo);
+    font-weight: var(--font-weight-bold);
+    letter-spacing: var(--letter-spacing-logo);
+  }
+
+  .site-nav :where(ul) {
+    display: flex;
+    flex-wrap: wrap;
+    align-items: center;
+    gap: var(--space-6);
+    list-style: none;
+  }
+
+  .site-nav :where(a) {
+    color: inherit;
+    font-size: var(--font-size-nav);
+    transition: color var(--duration-interaction);
+  }
+
+  .site-nav :where(a:is(:hover, :focus-visible)) {
