-                                    </a>
-                                </li>
-                            ))}
-                        </ul>
-                    )}
-                </div>
-            </div>
-        </div>
-    );
+import { useEffect, useMemo, useState, type RefObject } from 'react';
+import Modal from './Modal';
+
+interface Article { slug: string; title: string; summary: string; }
+interface Props { id: string; dialogRef: RefObject<HTMLDialogElement | null>; activated: boolean; }
+
+export default function SearchFlyout({ id, dialogRef, activated }: Props) {
+  const [articles, setArticles] = useState<Article[]>([]);
+  const [searchTerm, setSearchTerm] = useState('');
+  const [status, setStatus] = useState('');
+
+  useEffect(() => {
+    if (!activated) return;
+    const controller = new AbortController();
+    setStatus('Loading articles…');
+    fetch(`${import.meta.env.BASE_URL}api/articles.json`, { signal: controller.signal })
+      .then(response => { if (!response.ok) throw new Error(); return response.json(); })
+      .then(data => { setArticles(data); setStatus(''); })
+      .catch(error => { if (error.name !== 'AbortError') setStatus('Unable to load articles. Please try again later.'); });
+    return () => controller.abort();
+  }, [activated]);
+
+  const query = searchTerm.trim().toLowerCase();
+  const results = useMemo(() => query
+    ? articles.filter(article => `${article.title} ${article.summary}`.toLowerCase().includes(query))
+    : articles.slice(0, 3), [articles, query]);
+
+  return (
+    <Modal ref={dialogRef} id={id} title="Search articles">
+      <search>
+        <form onSubmit={event => event.preventDefault()}>
+          <label htmlFor={`${id}-query`} className="block text-sm font-semibold mb-2">Search</label>
+          <input id={`${id}-query`} name="q" type="search" enterKeyHint="search" autoCapitalize="none" autoCorrect="off" spellCheck={false}
+            placeholder="Search for articles…" className="w-full p-2 border border-gray-500 rounded-md"
+            value={searchTerm} onChange={event => setSearchTerm(event.target.value)} autoFocus />
+        </form>
+      </search>
+      <p role="status" className="text-sm text-gray-600 my-3">{status || (query ? `${results.length} results` : 'Featured articles')}</p>
+      <ul className="space-y-2">
+        {results.map(article => (
+          <li key={article.slug}>
+            <a href={`${import.meta.env.BASE_URL}articles/${article.slug}`} className="block hover:bg-gray-100 p-4 rounded-md">
+              <h3 className="font-bold text-lg text-gray-800">{article.title}</h3>
+              <p className="text-sm text-gray-600">{article.summary}</p>
+            </a>
+          </li>
+        ))}
+      </ul>
+    </Modal>
+  );
 }
