new file mode 100644
index 0000000..7926359
--- /dev/null
+++ b/src/components/Modal.tsx
@@ -0,0 +1,44 @@
+import { useEffect, useRef, type ReactNode } from 'react';
+
+interface Props {
+  id: string;
+  labelledBy: string;
+  onClose: () => void;
+  children: ReactNode;
+}
+
+export default function Modal({ id, labelledBy, onClose, children }: Props) {
+  const dialogRef = useRef<HTMLDialogElement>(null);
+
+  useEffect(() => {
+    const dialog = dialogRef.current!;
+    const trigger = document.activeElement instanceof HTMLElement ? document.activeElement : null;
+    dialog.showModal();
+    return () => {
+      dialog.close();
+      if (trigger?.isConnected) trigger.focus();
+    };
+  }, []);
+
+  return (
+    <dialog
+      ref={dialogRef}
+      id={id}
+      aria-labelledby={labelledBy}
+      className="overlay-dialog"
+      onClose={onClose}
+      onClick={event => {
+        if (event.target !== event.currentTarget) return;
+        const rect = event.currentTarget.getBoundingClientRect();
+        if (event.clientX < rect.left || event.clientX > rect.right || event.clientY < rect.top || event.clientY > rect.bottom) {
+          event.currentTarget.close();
+        }
+      }}
+    >
+      <button type="button" aria-label="Close dialog" className="absolute top-3 right-3 p-2 text-gray-600 hover:text-amber-700" onClick={() => dialogRef.current?.close()}>
+        <span aria-hidden="true">✕</span>
+      </button>
+      {children}
+    </dialog>
+  );
+}
