+          <label htmlFor="article-search" className="block text-sm font-semibold mb-2">Search by title or summary</label>
+          <input id="article-search" name="q" type="search" autoComplete="off" autoFocus value={query} onChange={event => setQuery(event.target.value)} className="w-full p-2 border border-gray-300 rounded-md" />
+        </form>
+        <p role="status" className="text-sm text-gray-600 my-4">
+          {loading ? 'Loading articles…' : error || (query.trim() ? `${results.length} results` : 'Featured articles')}
+        </p>
+        <ul className="space-y-2">
+          {results.map(article => (
+            <li key={article.slug}>
+              <a href={`${import.meta.env.BASE_URL}articles/${article.slug}`} className="block hover:bg-gray-100 p-4 rounded-md">
+                <h3 className="font-bold text-lg">{article.title}</h3>
+                <p className="text-sm text-gray-600">{article.summary}</p>
+              </a>
+            </li>
+          ))}
+        </ul>
+      </div>
+    </Modal>
+  );
 }
