new file mode 100644
index 0000000..ed79947
--- /dev/null
+++ b/tests/passkeys.test.js
@@ -0,0 +1,85 @@
+import test from 'node:test';
+import assert from 'node:assert/strict';
+import { createPasskeyStore } from '../passkeys.js';
+
+function memoryStorage() {
+  const data = new Map();
+  return { getItem: key => data.get(key) ?? null, setItem: (key, value) => data.set(key, value) };
+}
+const account = { rpId: 'coffee.example', passkeys: [{ id: 'key/1', name: 'Laptop', credentialId: 'Y3JlZGVudGlhbA' }] };
+const response = (status, data) => ({ ok: status >= 200 && status < 300, status, json: async () => structuredClone(data) });
+
+test('demo edits persist across reloads, including an empty list, without authenticator signals', async () => {
+  const storage = memoryStorage();
+  let signals = 0;
+  const options = { storage, credentialAPI: { signalUnknownCredential: () => signals++ } };
+  const store = createPasskeyStore(options);
+  await store.load();
+  await store.rename('macbook', '  Work laptop  ');
+  const reloaded = createPasskeyStore(options);
+  await reloaded.load();
+  assert.equal(reloaded.keys[0].name, 'Work laptop');
+  for (const key of reloaded.keys) assert.equal(await reloaded.remove(key.id), 'demo');
+  await store.load();
+  assert.equal(store.keys.length, 0);
+  assert.equal(signals, 0);
+});
+
+test('invalid names and storage failures leave existing data intact', async () => {
+  const store = createPasskeyStore({ storage: { setItem() { throw new Error('Storage full'); } } });
+  await store.load();
+  await assert.rejects(store.rename('macbook', '  '), /between 1 and 60/);
+  await assert.rejects(store.rename('macbook', 'a'.repeat(61)), /between 1 and 60/);
+  await assert.rejects(store.remove('macbook'), /Storage full/);
+  assert.equal(store.keys.length, 3);
+});
+
+test('deletion signals the exact credential only after server confirmation', async () => {
+  const events = [];
+  const store = createPasskeyStore({ apiBase: '/api/account/passkeys', csrfToken: 'csrf', request: async (url, options) => {
+    if (!options.method) return response(200, account);
+    events.push('deleted');
+    assert.equal(url, '/api/account/passkeys/key%2F1');
+    assert.equal(options.credentials, 'same-origin');
+    assert.equal(options.headers['X-CSRF-Token'], 'csrf');
+    return response(204);
+  }, credentialAPI: { async signalUnknownCredential(value) {
+    events.push('signaled');
+    assert.deepEqual(value, { rpId: account.rpId, credentialId: account.passkeys[0].credentialId });
+  } } });
+  await store.load();
+  assert.equal(await store.remove('key/1'), 'signaled');
+  assert.deepEqual(events, ['deleted', 'signaled']);
+  assert.equal(store.keys.length, 0);
+});
+
+test('failed deletion does not remove or signal a credential', async () => {
+  let signals = 0;
+  const store = createPasskeyStore({ apiBase: '/api/account/passkeys', request: async (_, options) => response(options.method ? 401 : 200, account), credentialAPI: { signalUnknownCredential: () => signals++ } });
+  await store.load();
+  await assert.rejects(store.remove('key/1'), /session has expired/);
+  assert.equal(store.keys.length, 1);
+  assert.equal(signals, 0);
+});
+
+test('unsupported browsers and rejected signals do not undo successful account deletion', async () => {
+  for (const [credentialAPI, expected] of [[{}, 'unsupported'], [{ signalUnknownCredential: async () => { throw new Error('Rejected'); } }, 'failed']]) {
+    const store = createPasskeyStore({ apiBase: '/api/account/passkeys', credentialAPI, request: async (_, options) => response(options.method ? 204 : 200, account) });
+    await store.load();
+    assert.equal(await store.remove('key/1'), expected);
+    assert.equal(store.keys.length, 0);
+  }
+});
+
+test('rename persists the trimmed account label without signaling user details', async () => {
+  let sent;
+  const store = createPasskeyStore({ apiBase: '/api/account/passkeys', request: async (_, options) => {
+    if (options.method) { sent = options; return response(204); }
+    return response(200, account);
+  } });
+  await store.load();
+  await store.rename('key/1', '  Home laptop  ');
+  assert.equal(sent.method, 'PATCH');
+  assert.deepEqual(JSON.parse(sent.body), { name: 'Home laptop' });
+  assert.equal(store.keys[0].name, 'Home laptop');
+});

