+import { test } from "node:test";
+import assert from "node:assert/strict";
+import { sameOrigin, json } from "../src/lib/http.ts";
+
+test("accepts same-origin mutations and rejects missing or foreign origins", () => {
+  assert.equal(
+    sameOrigin(
+      new Request("https://example.com/api", {
+        headers: { Origin: "https://example.com" },
+      }),
+    ),
+    true,
+  );
+  assert.equal(
+    sameOrigin(
+      new Request("https://example.com/api", {
+        headers: { Origin: "https://attacker.example" },
+      }),
+    ),
+    false,
+  );
+  assert.equal(sameOrigin(new Request("https://example.com/api")), false);
+  assert.equal(
+    sameOrigin(
+      new Request("https://example.com/api", { headers: { Origin: "null" } }),
+    ),
+    false,
+  );
+});
+test("account responses cannot be cached", async () => {
+  const response = json({ error: "Sign in required" }, 401);
+  assert.equal(response.status, 401);
+  assert.equal(response.headers.get("Cache-Control"), "no-store");
+  assert.deepEqual(await response.json(), { error: "Sign in required" });
+});
