+test('registration rejects account switching, wrong challenges, and absent user verification', async () => {
+  const { verifyPasskeyRegistration } = await import('../src/server/passkeys');
+  const { response, expected } = await registration();
+  await assert.rejects(verifyPasskeyRegistration(response, expected, 'another-account'), /Account does not match/);
+  await assert.rejects(verifyPasskeyRegistration(response, { ...expected, challenge: randomBytes(32).toString('base64url') }, expected.userId), /challenge/i);
+  const unverified = await registration(0x41);
+  await assert.rejects(verifyPasskeyRegistration(unverified.response, unverified.expected, unverified.expected.userId), /verification/i);
