+/* Account experiences share the quiet, editorial character of the newspaper. */
+:root {
+  --account-ink: #202a27;
+  --account-green: #164f40;
+  --account-muted: #727873;
+  --account-line: #e3e7e3;
+}
+.account-breadcrumb {
+  margin: 0 48px;
+  padding: 23px 0;
+  display: flex;
+  align-items: center;
+  gap: 13px;
+  border-bottom: 1px solid var(--account-line);
+  color: #8b918b;
+  font:
+    11px Arial,
+    sans-serif;
+}
+.account-breadcrumb a {
+  color: #5c655f;
+}
+.account-breadcrumb > span:nth-child(3) {
+  color: #343f38;
+}
+.secure-connection {
+  margin-left: auto;
+  display: flex;
+  align-items: center;
+  gap: 7px;
+  font-size: 9px;
+  letter-spacing: 1.25px;
