1/schedule-tasks-by-priority/task/guided:
diff --git a/index.html b/index.html
--- a/index.html
+++ b/index.html
@@ -134,8 +134,67 @@
     .btn:hover {
       background: #3e2723;
     }

+    /* Operations simulator */
+    .operations {
+      margin-top: 48px;
+      padding: 28px;
+      background: #fffdf9;
+      border: 1px solid #e4d9d0;
+      border-radius: 12px;
+    }
+
+    .operations-header, .queue-heading, .queue-footer {
+      display: flex;
+      align-items: center;
+      justify-content: space-between;
+      flex-wrap: wrap;
+      gap: 12px;
+    }
+
+    .operations .eyebrow {
+      color: #766458;
+      font-size: .72rem;
+      font-weight: 700;
+      letter-spacing: .14em;
+      text-transform: uppercase;
+    }
+
+    .operations h2 { margin: 4px 0; font-size: 1.6rem; }
+    .operations-description { color: #766458; font-size: .9rem; margin-top: 8px; }
+    .queue-indicator { border-radius: 20px; background: #edf2e9; color: #405439; padding: 5px 12px; font-size: .78rem; }
+    .queue-indicator::before { content: ''; display: inline-block; width: 7px; height: 7px; background: #58734a; border-radius: 50%; margin-right: 7px; }
+    .task-actions { display: grid; grid-template-columns: repeat(3, minmax(0, 1fr)); gap: 12px; margin: 24px 0 16px; }
+    .operations button { font: inherit; cursor: pointer; }
+    .task-button { text-align: left; border: 1px solid #e4d9d0; border-radius: 8px; background: white; color: var(--text); padding: 16px; }
+    .task-button:hover { background: #f7f1e9; border-color: #ac8e76; }
+    .task-button strong { display: block; font-size: .95rem; margin: 10px 0 4px; }
+    .task-button small { display: block; color: #766458; font-size: .8rem; }
+    .priority { display: inline-block; font-size: .65rem; font-weight: 700; letter-spacing: .07em; text-transform: uppercase; padding: 3px 7px; border-radius: 4px; background: #f9e5df; color: #923e2b; }
+    .priority.standard { background: #fbefd3; color: #795717; }
+    .priority.background { background: #e9eeeb; color: #496452; }
+    .batch-button { border: 0; margin: 0; font-weight: 600; }
+    .queue-footer > p { font-size: .8rem; color: #766458; }
+    .queue-panel { margin-top: 24px; border-top: 1px solid #e4d9d0; padding-top: 20px; }
+    .queue-heading h3 { font-size: .9rem; }
+    .queue-heading span { font-size: .78rem; color: #766458; }
+    .queue-tasks { list-style: none; margin-top: 12px; }
+    .queue-task { padding: 10px 0; border-bottom: 1px solid #eee6df; }
+    .queue-task > div { display: flex; justify-content: space-between; gap: 12px; font-size: .83rem; }
