+      box-sizing: border-box;
+      margin: 0;
+      padding: 0;
+    }
+
+    article {
+      height: 100%;
+      background: white;
+      padding: 20px;
+      border-radius: 8px;
+      box-shadow: 0 2px 5px rgba(0, 0, 0, 0.1);
+      text-align: center;
+    }
+
+    h3 {
+      margin-bottom: 10px;
+      color: #4e342e;
+    }
+
+    .badge {
+      display: none;
+      margin-bottom: 10px;
+      padding: 2px 8px;
+      border-radius: 4px;
+      background: #ffab40;
+      color: #3e2723;
+      font-size: 0.75rem;
+      font-weight: bold;
+    }
+
+    :host([limited]) .badge {
+      display: inline-block;
+    }
+
+    a {
+      display: inline-block;
+      background: #4e342e;
+      color: white;
+      padding: 10px 20px;
+      text-decoration: none;
+      border-radius: 5px;
+      margin-top: 15px;
+      transition: background 0.3s;
+    }
+
+    a:hover {
+      background: #3e2723;
+    }
+  </style>
+  <article>
+    <span class="badge">Limited</span>
+    <h3></h3>
+    <p></p>
+    <a></a>
+  </article>
+`;
+
+class SeasonalCard extends HTMLElement {
+  static observedAttributes = ['drink-title', 'description', 'action-href', 'action-label'];
+
+  constructor() {
+    super();
+    this.attachShadow({ mode: 'open', delegatesFocus: true });
+    this.shadowRoot.append(template.content.cloneNode(true));
+  }
+
+  connectedCallback() {
+    this.render();
+  }
+
+  attributeChangedCallback(name, oldValue, newValue) {
+    if (oldValue !== newValue) this.render();
+  }
+
+  render() {
+    this.shadowRoot.querySelector('h3').textContent = this.getAttribute('drink-title') ?? '';
+    this.shadowRoot.querySelector('p').textContent = this.getAttribute('description') ?? '';
+
+    const action = this.shadowRoot.querySelector('a');
+    action.textContent = this.getAttribute('action-label') ?? 'View Details';
+    const href = this.getAttribute('action-href');
+    if (href === null) {
+      action.removeAttribute('href');
+    } else {
+      action.setAttribute('href', href);
+    }
+  }
+}
+
+customElements.define('seasonal-card', SeasonalCard);

