@@ -0,0 +1,31 @@
+// Keep both sanitizers restricted to the markup needed by the seasonal cards.
+const elements = ['div', 'h3', 'p', 'a'];
+const attributes = ['class', 'href'];
+let domPurifyModule;
+const purifiers = new WeakMap();
+
+export async function safeSetHTML(element, html) {
+  if ('setHTML' in element) {
+    element.setHTML(html, { sanitizer: { elements, attributes } });
+    return;
+  }
+
+  // Load the local fallback only in browsers without the native Sanitizer API.
+  domPurifyModule ??= import('./vendor/purify.es.mjs');
+  const { default: createDOMPurify } = await domPurifyModule;
+  const view = element.ownerDocument.defaultView;
+  if (!purifiers.has(view)) purifiers.set(view, createDOMPurify(view));
+  const purifier = purifiers.get(view);
+  if (!purifier.isSupported) throw new Error('HTML sanitization is unavailable');
+
+  // DOMPurify's named policy supplies TrustedHTML under Trusted Types enforcement.
+  // Never fall back to inserting the original string if sanitization fails.
+  element.innerHTML = purifier.sanitize(html, {
+    ALLOWED_TAGS: [...elements, '#text'],
+    ALLOWED_ATTR: attributes,
+    ALLOW_ARIA_ATTR: false,
+    ALLOW_DATA_ATTR: false,
+    KEEP_CONTENT: false,
+    RETURN_TRUSTED_TYPE: true,
+  });
+}
