+import assert from 'node:assert/strict';
+import { readFile } from 'node:fs/promises';
+import test from 'node:test';
+import { JSDOM } from 'jsdom';
+import { safeSetHTML } from '../safe-html.mjs';
+import { renderSeasonalFavorites } from '../seasonal-favorites.mjs';
+
+function fixture() {
+  const dom = new JSDOM('<div id="cards"></div>', { url: 'https://daily-grind.example/' });
+  return { dom, container: dom.window.document.getElementById('cards') };
+}
+
+test('renders all three HTML cards with their original details and links', async () => {
+  const { dom, container } = fixture();
+  try {
+    await renderSeasonalFavorites(container);
+    assert.deepEqual([...container.querySelectorAll('.card h3')].map((el) => el.textContent),
+      ['Maple Oat Latte', 'Dark Roast Espresso', 'Cold Brew']);
+    assert.deepEqual([...container.querySelectorAll('.btn')].map((el) => el.getAttribute('href')),
+      ['/menu/seasonal', '/menu/espresso', '/menu/cold-brew']);
+    assert.equal(container.querySelectorAll('.card p').length, 3);
+    await renderSeasonalFavorites(container);
+    assert.equal(container.querySelectorAll('.card').length, 3, 're-render replaces existing cards');
+  } finally { dom.window.close(); }
+});
+
+test('fallback strips XSS payloads, dangerous URLs and unwanted markup', async () => {
+  const { dom, container } = fixture();
+  try {
+    await renderSeasonalFavorites(container, [
+      `<div class="card" id="location" onclick="alert(1)" style="color:red" data-x="bad">
+        <h3>Safe coffee</h3><p>Keep this description.</p>
+        <script>alert(1)</script><img src=x onerror=alert(1)>
+        <svg><a xlink:href="javascript:alert(1)">bad</a></svg>
+        <math><mtext><img src=x onerror=alert(1)></mtext></math>
+        <iframe srcdoc="<script>alert(1)</script>"></iframe>
+        <form name="document"><input name="location"></form>
+        <style>body{display:none}</style><template><img src=x onerror=alert(1)></template>
+        <a href="javascript:alert(1)">bad link</a>
+        <a href="&#106;avascript:alert(1)">encoded link</a>
+        <a href="java&#x09;script:alert(1)">control character</a>
+        <a href="data:text/html,bad">data link</a>
+        <a href="/menu/seasonal" class="btn" onmouseover="alert(1)">View Details</a>
+      </div>`,
+      // Malformed foreign-content payload used to exercise mutation-XSS defenses.
+      '<math><mtext><table><mglyph><style><!--</style><img title="--><img src=x onerror=alert(1)>">',
+    ]);
+    const tags = new Set(['DIV', 'H3', 'P', 'A']);
+    for (const element of container.querySelectorAll('*')) {
+      assert.ok(tags.has(element.tagName), `unexpected tag ${element.tagName}`);
+      for (const attribute of element.attributes) {
+        assert.ok(['class', 'href'].includes(attribute.name), `unexpected attribute ${attribute.name}`);
+      }
+    }
+    assert.equal(container.querySelector('h3').textContent, 'Safe coffee');
+    assert.equal(container.querySelector('p').textContent, 'Keep this description.');
+    assert.deepEqual([...container.querySelectorAll('[href]')].map((el) => el.getAttribute('href')),
+      ['/menu/seasonal']);
+  } finally { dom.window.close(); }
+});
+
+test('native branch passes strings and a restrictive config to setHTML without using innerHTML', async () => {
+  const { dom, container } = fixture();
+  try {
+    let received;
+    container.setHTML = (html, options) => { received = { html, options }; };
+    Object.defineProperty(container, 'innerHTML', { set() { assert.fail('unsafe sink used'); } });
+    const input = '<h3>Coffee</h3><script>alert(1)</script>';
+    await safeSetHTML(container, input);
+    assert.equal(received.html, input);
+    assert.deepEqual(received.options.sanitizer,
+      { elements: ['div', 'h3', 'p', 'a'], attributes: ['class', 'href'] });
+  } finally { dom.window.close(); }
+});
+
+test('fallback uses TrustedHTML when Trusted Types is available', async () => {
+  const { dom, container } = fixture();
+  try {
+    // Simulate type enforcement at the insertion sink; jsdom does not implement CSP.
+    class TrustedHTML {
+      constructor(value) { this.value = value; }
+      toString() { return this.value; }
+    }
+    const names = [];
+    dom.window.trustedTypes = {
+      createPolicy(name, rules) {
+        names.push(name);
+        assert.equal(name, 'dompurify');
+        return {
+          createHTML: (value) => new TrustedHTML(rules.createHTML(value)),
+          createScriptURL: rules.createScriptURL,
+        };
+      },
+      isHTML: (value) => value instanceof TrustedHTML,
+    };
+    const descriptor = Object.getOwnPropertyDescriptor(dom.window.Element.prototype, 'innerHTML');
+    Object.defineProperty(container, 'innerHTML', {
+      get() { return descriptor.get.call(this); },
+      set(value) {
+        assert.ok(value instanceof TrustedHTML, 'sink must receive TrustedHTML');
+        descriptor.set.call(this, String(value));
+      },
+    });
+    await safeSetHTML(container, '<h3 onclick="alert(1)">Coffee</h3>');
+    assert.equal(container.innerHTML, '<h3>Coffee</h3>');
+    assert.deepEqual(names, ['dompurify']);
+  } finally { dom.window.close(); }
+});
+
+test('homepage declares enforcement before other resources and wires the dynamic renderer', async () => {
+  const html = await readFile(new URL('../index.html', import.meta.url), 'utf8');
+  const dom = new JSDOM(html);
+  try {
+    const { document } = dom.window;
+    const policy = document.head.firstElementChild;
+    assert.equal(policy.getAttribute('http-equiv'), 'Content-Security-Policy');
+    assert.match(policy.content, /require-trusted-types-for 'script'/);
+    assert.match(policy.content, /trusted-types dompurify;/);
+    assert.ok(!policy.content.includes('default'), 'no permissive default policy');
+    assert.equal(document.querySelectorAll('#seasonal-favorites').length, 1);
+    assert.equal(document.querySelector('#seasonal-favorites').children.length, 0);
+    assert.equal(document.querySelector('script[type="module"]').getAttribute('src'), './homepage.mjs');
+  } finally { dom.window.close(); }
+});
